(({F:e})=>{e.push({code:"pt-br",prevText:"Anterior",nextText:"Próximo",prevYearText:"Ano anterior",nextYearText:"Próximo ano",yearText:"Ano",todayText:"Hoje",monthText:"Mês",weekTextLong:"Semana",weekTextShort:"Sm",dayText:"Dia",listText:"Lista",prevHint:"$0 Anterior",nextHint:"Próximo $0",todayHint(e,t){return"day"===t?"Hoje":("week"===t?"Esta":"Este")+" "+e.toLocaleLowerCase()},viewHint(e,t){return"Visualizar "+("week"===t?"a":"o")+" "+e.toLocaleLowerCase()},allDayText:"Dia\ninteiro",moreLinkText(e){return"mais +"+e},moreLinkHint(e){return`Mostrar mais ${e} eventos`},noEventsText:"Não há eventos para mostrar",navLinkHint:"Ir para $0",closeHint:"Fechar",eventsHint:"Eventos"})})(FullCalendar.Shared);